typedef unsigned long long big_int;
class string_buf {
public:
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
    inline int compare(const char *str) const {
        int i;
        const char *a = reinterpret_cast<const char *>(data);
        for (i = 0; i < char_length; i++) {
            if (str[i] == '\0') return -1;
            if (a[i] == str[i]) continue;
            if (str[i] > a[i]) return 1;
            if (str[i] < a[i]) return -1;
        }
        if (str[i] == '\0') return 0;
        return 1;
    }
    inline bool is_equal(const char *str) const { return (compare(str) == 0); }
};
class stringx {
public:
    char *chars;
    string_buf *my_buf;
};
inline bool operator==(const stringx& lhs, const char *rhs) { return lhs.my_buf->is_equal(rhs); }
struct script_mfg {};
struct game { char padding[0x50]; script_mfg m_script_mfg; script_mfg *get_script_mfg() { return &m_script_mfg; } };
extern game *g_game_ptr;
__asm__(".equ g_game_ptr, 0x0045AC64");
class slc_mfg_t { public: unsigned find_instance(const stringx& n) const; };
unsigned slc_mfg_t::find_instance(const stringx& n) const
{
  if (n=="NULL") return (unsigned)0;
  if (n=="MFG") return (unsigned)g_game_ptr->get_script_mfg();

  return (unsigned)0;
}
